#include <iostream>
#include <string>
#include <vector>

using namespace std;

// Função para somar 1 a uma representação de número em string
void increment(string &s) {
    int n = s.size();
    int carry = 1;
    for (int i = n - 1; i >= 0 && carry; --i) {
        int sum = (s[i] - '0') + carry;
        s[i] = (sum % 10) + '0';
        carry = sum / 10;
    }
    if (carry) {
        s.insert(s.begin(), '1');
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    string s = "";
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c;
        s += c;
    }

    if (s[0] == '0') {
        // Pelo enunciado 1 <= A, portanto o primeiro dígito nunca é '0'
        return 0;
    }

    for (int len = 1; len <= n; ++len) {
        string A = s.substr(0, len);
        string cur = A;
        int idx = len;
        bool ok = true;

        while (idx < n) {
            increment(cur);
            int cur_len = cur.size();
            if (idx + cur_len > n) {
                ok = false;
                break;
            }
            if (s.compare(idx, cur_len, cur) != 0) {
                ok = false;
                break;
            }
            idx += cur_len;
        }

        if (ok && idx == n) {
            cout << A << "\n";
            return 0;
        }
    }

    return 0;
}
